'use client';

import { useEffect, useRef, useState } from 'react';
import dynamic from 'next/dynamic';
import InfoSection from '@/components/InfoSection';
import { DEBUG_ORBIT_CONTROLS } from '@/components/Scene';

// Scene uses WebGL / browser APIs only — load it client-side, no SSR.
const Scene = dynamic(() => import('@/components/Scene'), { ssr: false });

export default function Home() {
  const scrollProgress = useRef(0);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setLoaded(true);

    const onScroll = () => {
      const scrollable = document.body.scrollHeight - window.innerHeight;
      scrollProgress.current = scrollable > 0 ? window.scrollY / scrollable : 0;
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <main className="relative">
      {/* Fixed 3D background — camera moves as the page scrolls */}
      {loaded && <Scene scrollProgress={scrollProgress} />}

      {/* Scrollable HTML content sitting on top of the fixed canvas */}
      <div className="relative z-10">
        <section className="h-screen flex flex-col items-center justify-center text-center px-6">
          <p className="text-[#C9A94E] text-xs tracking-[0.4em] font-semibold mb-4">
            RAGHAVA CONSTRUCTIONS
          </p>
          <h1 className="text-white text-5xl md:text-7xl font-serif mb-6">
            CINQ
          </h1>
          <p className="text-white/60 text-base md:text-lg max-w-md">
            61 floors above the ordinary. Scroll to descend through the tower.
          </p>
          <div className="mt-16 text-white/30 text-xs tracking-widest animate-bounce">
            SCROLL ↓
          </div>
        </section>

        <InfoSection
          eyebrow="SKY AMENITIES"
          title="Where the city ends and the sky begins"
          body="Infinity pool, sky lounge, and observatory deck at the tower's crown — panoramic views of the Financial District from Hyderabad's most ambitious address."
          align="right"
        />

        <InfoSection
          eyebrow="THE RESIDENCES"
          title="4 BHK sanctuaries in the sky"
          body="3,600 sqft residences, only four per floor, with personal elevators and floor-to-ceiling glazing framing the city below."
          align="left"
        />

        <InfoSection
          eyebrow="MID-SKY CLUB"
          title="55,000 sqft of curated leisure"
          body="A clubhouse built for balance — gym, spa, theatre, and business center, suspended mid-tower for residents only."
          align="right"
        />

        <InfoSection
          eyebrow="THE FOUNDATION"
          title="Rooted in the Financial District"
          body="Two minutes from ORR, moments from Hyderabad's biggest employers — CINQ is built where ambition already lives."
          align="left"
        />

        <section className="h-screen flex flex-col items-center justify-center text-center px-6">
          <h2 className="text-white text-4xl md:text-6xl font-serif mb-6">
            Experience CINQ
          </h2>
          <p className="text-white/60 mb-10">Book a private site visit today.</p>
          <button className="px-8 py-4 bg-[#C9A94E] text-black font-semibold rounded-full hover:bg-white transition-colors">
            Book a Site Visit
          </button>
        </section>
      </div>
    </main>
  );
}
